import pandas as pd
import numpy as np

def harmonize_row(row):
    # Serum_Creatinine: mg/dL (US) vs umol/L (SI). Factor: SI / 88.4
    if row['Serum_Creatinine'] > 30:
        row['Serum_Creatinine'] /= 88.4

    # Hemoglobin: g/dL (US) vs g/L (SI). Factor: SI / 10
    if row['Hemoglobin'] > 30:
        row['Hemoglobin'] /= 10

    # Glucose: mg/dL (US) vs mmol/L (SI). Factor: SI * 18.0182
    if row['Glucose'] < 30:
        row['Glucose'] *= 18.0182

    # Cholesterol (Total, LDL, HDL, Non_HDL): mg/dL (US) vs mmol/L (SI). Factor: SI * 38.67
    for col in ['Total_Cholesterol', 'LDL_Cholesterol', 'HDL_Cholesterol', 'Non_HDL_Cholesterol']:
        if col in row and row[col] < 15:
            row[col] *= 38.67

    # Triglycerides: mg/dL (US) vs mmol/L (SI). Factor: SI * 88.57
    if 'Triglycerides' in row and row['Triglycerides'] < 20:
        row['Triglycerides'] *= 88.57

    # Bilirubin (Total, Direct): mg/dL (US) vs umol/L (SI). Factor: SI / 17.1
    for col in ['Total_Bilirubin', 'Direct_Bilirubin']:
        if col in row and row[col] > 5:
            row[col] /= 17.1

    # Uric Acid: mg/dL (US) vs umol/L (SI). Factor: SI / 59.48
    if 'Uric_Acid' in row and row['Uric_Acid'] > 50:
        row['Uric_Acid'] /= 59.48

    # Albumin_Serum: g/dL (US) vs g/L (SI). Factor: SI / 10
    if 'Albumin_Serum' in row and row['Albumin_Serum'] > 10:
        row['Albumin_Serum'] /= 10

    # Total_Protein: g/dL (US) vs g/L (SI). Factor: SI / 10
    if 'Total_Protein' in row and row['Total_Protein'] > 20:
        row['Total_Protein'] /= 10

    # Serum_Calcium: mg/dL (US) vs mmol/L (SI). Factor: SI * 4
    if 'Serum_Calcium' in row and row['Serum_Calcium'] < 4:
        row['Serum_Calcium'] *= 4

    # Phosphorus: mg/dL (US) vs mmol/L (SI). Factor: SI * 3.1
    if 'Phosphorus' in row and row['Phosphorus'] < 2:
        row['Phosphorus'] *= 3.1

    # Magnesium: mg/dL (US) vs mmol/L (SI). Factor: SI * 2.43
    if 'Magnesium' in row and row['Magnesium'] < 1.2:
        row['Magnesium'] *= 2.43

    return row

def main():
    # Load data
    df = pd.read_csv('/root/environment/data/ckd_lab_data.csv', dtype=str)

    # Clean data: handle commas and scientific notation
    for col in df.columns:
        if col == 'patient_id':
            continue
        df[col] = df[col].str.replace(',', '.')
        df[col] = pd.to_numeric(df[col], errors='coerce')

    # Drop rows with missing values
    df = df.dropna()

    # Harmonize units
    df = df.apply(harmonize_row, axis=1)

    # Round to 2 decimal places
    # Use applymap to format as string with 2 decimal places
    output_df = df.copy()
    for col in output_df.columns:
        if col == 'patient_id':
            output_df[col] = output_df[col].astype(int).astype(str)
        else:
            output_df[col] = output_df[col].map(lambda x: f"{x:.2f}")

    # Save harmonized data
    output_df.to_csv('/root/ckd_lab_data_harmonized.csv', index=False)

if __name__ == "__main__":
    main()

